export type TrackingMode = 'moving' | 'static';
export type SourceType = 'webcam' | 'gallery';
export type LabelAlign = 'left' | 'center' | 'right';
export type LabelPosition = 'top' | 'bottom';
export type SequenceSort = 'y' | 'x';

export interface TrackerConfig {
  mode: TrackingMode;
  sourceType: SourceType;
  videoUrl: string | null;
  loop: boolean;
  threshold: number;
  minArea: number;
  maxArea: number;
  showMask: boolean;
  history: number;
  varThreshold: number;
  showLabels: boolean;
  processingFPS: number; 
  // Aesthetic Props
  trackerColor: string;
  strokeWeight: number;
  connectNearby: boolean;
  connectionMaxDist: number;
  connectSequence: boolean;
  sequenceSort: SequenceSort;
  fontFamily: string;
  labelSize: number;
  labelPrefix: string;
  showLabelNumber: boolean;
  showCenterDot: boolean;
  borderRadius: number;
  labelAlign: LabelAlign;
  labelPosition: LabelPosition;
  labelColor: string;
}

export interface BlobData {
  x: number;
  y: number;
  w: number;
  h: number;
  area: number;
  id: number;
}

import React, { useState, useRef } from 'react';

// Inline SVG icons — replaces lucide-react ChevronDown, Check, Plus
const CheckIcon = ({ size = 12, strokeWidth = 3 }: { size?: number; strokeWidth?: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" 
    strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round">
    <polyline points="20 6 9 17 4 12"/>
  </svg>
);

const PlusIcon = ({ size = 12 }: { size?: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" 
    strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/>
  </svg>
);

export const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ display: 'flex', alignItems: 'center', padding: '0 8px' }}>
    <span style={{
      fontSize: '11px', fontWeight: 500, color: 'rgba(218,220,224,0.9)',
      letterSpacing: '0.1px'
    }}>
      {children}
    </span>
  </div>
);

export const ColorPicker: React.FC<{
  label: string;
  value: string;
  onChange: (color: string) => void;
}> = ({ label, value, onChange }) => {
  const colorInputRef = useRef<HTMLInputElement | null>(null);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', width: '100%' }}>
      <span style={{
        fontSize: '11px', fontWeight: 500, color: 'rgba(255,255,255,0.35)',
        letterSpacing: '0.1px', padding: '0 8px'
      }}>
        {label}
      </span>
      <button
        onClick={() => colorInputRef.current?.click()}
        style={{
          position: 'relative', display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          width: '100%', height: '34px', padding: '0 12px', borderRadius: '12px',
          border: '1px solid #595959', background: 'transparent', cursor: 'pointer',
          overflow: 'hidden', transition: 'all 0.2s'
        }}
      >
        <span style={{
          fontSize: '11px', fontFamily: 'monospace', color: 'rgba(218,220,224,0.75)',
          letterSpacing: '0.1em', transition: 'color 0.2s'
        }}>
          {value}
        </span>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <div 
            style={{
              width: '16px', height: '16px', borderRadius: '50%',
              border: '1px solid rgba(255,255,255,0.1)',
              boxShadow: '0 4px 6px -1px rgba(0,0,0,0.5)',
              backgroundColor: value
            }}
          />
          <PlusIcon size={12} />
        </div>
        <input 
          ref={colorInputRef}
          type="color" 
          value={value} 
          onChange={(e) => onChange(e.target.value)}
          style={{
            position: 'absolute', inset: 0, opacity: 0, cursor: 'pointer'
          }}
        />
      </button>
    </div>
  );
};

export const Checkbox: React.FC<{
  label: string;
  checked: boolean;
  onChange: (val: boolean) => void;
  icon?: React.ReactNode;
}> = ({ label, checked, onChange, icon }) => (
  <button
    onClick={() => onChange(!checked)}
    style={{
      display: 'flex', alignItems: 'center', justifyContent: 'space-between',
      width: '100%', height: '34px', padding: '0 12px', borderRadius: '12px',
      border: '1px solid #595959', background: 'transparent',
      transition: 'all 0.2s', cursor: 'pointer', color: 'inherit'
    }}
  >
    <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
      {icon && <span style={{ color: 'rgba(218,220,224,0.5)', transition: 'color 0.2s' }}>{icon}</span>}
      <span style={{
        fontSize: '11px', fontWeight: 500, color: 'rgba(218,220,224,0.75)',
        transition: 'color 0.2s', letterSpacing: '0.1px'
      }}>{label}</span>
    </div>
    <div style={{
      width: '16px', height: '16px', borderRadius: '6px',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      transition: 'all 0.2s',
      ...(checked 
        ? { background: '#969696', border: 'none' }
        : { border: '1px solid #595959' }
      )
    }}>
      {checked && (
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="black" 
          strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
          <polyline points="20 6 9 17 4 12"/>
        </svg>
      )}
    </div>
  </button>
);

export const PillButton: React.FC<{
  icon?: React.ReactNode; 
  children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; 
  onClick?: () => void;
  className?: string;
}> = ({ icon, children, variant = 'filled', onClick, className = '' }) => {
  const baseStyle: React.CSSProperties = {
    display: 'flex', alignItems: 'center', gap: '2px', justifyContent: 'center',
    width: '100%', height: '34px', borderRadius: '12px', fontWeight: 500,
    letterSpacing: '0.1px', transition: 'all 0.2s', cursor: 'pointer',
    border: 'none', outline: 'none'
  };

  const variantStyles: Record<string, React.CSSProperties> = {
    filled: {
      background: '#969696', color: 'black', fontSize: '11px',
      padding: '4px 24px 4px 8px', userSelect: 'none' as const
    },
    outline: {
      border: '1px solid #595959', background: 'transparent',
      backdropFilter: 'blur(40px)', fontSize: '12px',
      padding: '8px 16px 8px 8px', color: 'white', userSelect: 'none' as const
    },
    solid: {
      background: 'white', color: 'black', fontSize: '12px',
      padding: '8px 16px 8px 8px', userSelect: 'none' as const
    },
  };

  return (
    <button 
      className={className} 
      style={{ ...baseStyle, ...variantStyles[variant || 'filled'] }} 
      onClick={onClick}
    >
      {icon && <span style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', width: '24px', height: '24px' }}>{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

export const RangeSlider: React.FC<{
  label: string; value: number; min: number; max: number;
  step?: number; formatValue?: (val: number) => string;
  onChange: (val: number) => void;
}> = ({ label, value, min, max, step = 1, formatValue = (v) => String(v), onChange }) => (
  <div style={{
    display: 'flex', flexDirection: 'column', gap: 0, paddingTop: '4px', paddingBottom: '4px', width: '100%'
  }}>
    <div style={{
      display: 'flex', alignItems: 'center', justifyContent: 'space-between',
      padding: '0 8px', userSelect: 'none'
    }}>
      <span style={{
        fontSize: '11px', fontWeight: 500, color: 'rgba(218,220,224,0.9)',
        letterSpacing: '0.1px'
      }}>{label}</span>
      <span style={{
        fontSize: '11px', fontWeight: 500, color: '#c7c9cd', letterSpacing: '0.1px'
      }}>{formatValue(value)}</span>
    </div>
    <div style={{ width: '100%', display: 'flex', alignItems: 'center', height: '32px' }}>
      <input 
        type="range" 
        min={min} 
        max={max} 
        step={step} 
        value={value}
        onChange={(e) => onChange(Number(e.target.value))} 
      />
    </div>
  </div>
);

export const DualRangeSlider: React.FC<{
  label: string;
  min: number;
  max: number;
  minVal: number;
  maxVal: number;
  step?: number;
  onChange: (min: number, max: number) => void;
}> = ({ label, min, max, minVal, maxVal, step = 10, onChange }) => {
  const trackRef = useRef<HTMLDivElement | null>(null);
  const [dragging, setDragging] = useState<'min' | 'max' | 'bar' | null>(null);
  const dragStart = useRef<{ x: number; minVal: number; maxVal: number } | null>(null);

  const THUMB_R = 7; // thumb radius in px

  const pctFromVal = (v: number) => ((v - min) / (max - min)) * 100;
  const valFromPx = (px: number) => {
    if (!trackRef.current) return min;
    const rect = trackRef.current.getBoundingClientRect();
    // usable track area is inset by THUMB_R on each side
    const usable = rect.width - THUMB_R * 2;
    const ratio = Math.max(0, Math.min(1, (px - THUMB_R) / usable));
    const raw = min + ratio * (max - min);
    return Math.round(raw / step) * step;
  };

  const clamp = (v: number) => Math.max(min, Math.min(max, v));

  const handlePointerDown = (target: 'min' | 'max' | 'bar') => (e: React.PointerEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragging(target);
    dragStart.current = { x: e.clientX, minVal, maxVal };
    // Capture on the track container so onPointerMove fires there
    trackRef.current?.setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!dragging || !trackRef.current || !dragStart.current) return;
    const rect = trackRef.current.getBoundingClientRect();

    if (dragging === 'min') {
      const px = e.clientX - rect.left;
      const v = clamp(valFromPx(px));
      if (v < maxVal) onChange(v, maxVal);
    } else if (dragging === 'max') {
      const px = e.clientX - rect.left;
      const v = clamp(valFromPx(px));
      if (v > minVal) onChange(minVal, v);
    } else if (dragging === 'bar') {
      const dx = e.clientX - dragStart.current.x;
      const usable = rect.width - THUMB_R * 2;
      const dVal = Math.round((dx / usable) * (max - min) / step) * step;
      const span = dragStart.current.maxVal - dragStart.current.minVal;
      let newMin = dragStart.current.minVal + dVal;
      let newMax = dragStart.current.maxVal + dVal;
      // clamp window to bounds
      if (newMin < min) { newMin = min; newMax = min + span; }
      if (newMax > max) { newMax = max; newMin = max - span; }
      onChange(clamp(newMin), clamp(newMax));
    }
  };

  const handlePointerUp = () => {
    setDragging(null);
    dragStart.current = null;
  };

  const pctMin = pctFromVal(minVal);
  const pctMax = pctFromVal(maxVal);

  return (
    <div style={{
      display: 'flex', flexDirection: 'column', gap: 0, paddingTop: '4px', paddingBottom: '4px', width: '100%'
    }}>
      <div style={{
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        padding: '0 8px', userSelect: 'none', marginBottom: '4px'
      }}>
        <span style={{
          fontSize: '11px', fontWeight: 500, color: 'rgba(218,220,224,0.9)',
          letterSpacing: '0.1px'
        }}>{label}</span>
        <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
          <span style={{ fontSize: '10px', fontFamily: 'monospace', color: '#c7c9cd' }}>{minVal}</span>
          <span style={{ fontSize: '10px', color: 'rgba(218,220,224,0.3)' }}>/</span>
          <span style={{ fontSize: '10px', fontFamily: 'monospace', color: '#c7c9cd' }}>{maxVal}</span>
        </div>
      </div>

      {/* Track container */}
      <div
        ref={trackRef}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onLostPointerCapture={handlePointerUp}
        style={{
          position: 'relative', width: '100%', height: '32px',
          display: 'flex', alignItems: 'center',
          touchAction: 'none', userSelect: 'none',
          cursor: dragging === 'bar' ? 'grabbing' : undefined
        }}
      >
        {/* Inner track zone — inset by THUMB_R so thumbs stay within bounds */}
        <div style={{
          position: 'absolute',
          left: `${THUMB_R}px`, right: `${THUMB_R}px`,
          top: 0, bottom: 0,
        }}>
          {/* Background track (grey line) */}
          <div style={{
            position: 'absolute', left: 0, right: 0, top: '50%',
            transform: 'translateY(-50%)',
            height: '3px', background: '#595959', borderRadius: '9999px'
          }} />

          {/* Active track (white bar between thumbs — draggable) */}
          <div
            onPointerDown={handlePointerDown('bar')}
            style={{
              position: 'absolute',
              left: `${pctMin}%`,
              width: `${pctMax - pctMin}%`,
              top: '50%', transform: 'translateY(-50%)',
              height: '16px',
              display: 'flex', alignItems: 'center',
              cursor: dragging === 'bar' ? 'grabbing' : 'grab',
              zIndex: 10,
            }}
          >
            <div style={{
              width: '100%', height: '3px', background: 'white',
              borderRadius: '9999px', pointerEvents: 'none',
            }} />
          </div>

          {/* Min thumb */}
          <div
            onPointerDown={handlePointerDown('min')}
            style={{
              position: 'absolute',
              left: `${pctMin}%`,
              top: '50%',
              transform: 'translate(-50%, -50%)',
              width: `${THUMB_R * 2}px`, height: `${THUMB_R * 2}px`,
              borderRadius: '50%', background: 'white',
              boxShadow: '0px 1px 4px rgba(0,0,0,0.4)',
              cursor: 'pointer', zIndex: 20,
              transition: dragging ? 'none' : 'left 75ms',
            }}
          />

          {/* Max thumb */}
          <div
            onPointerDown={handlePointerDown('max')}
            style={{
              position: 'absolute',
              left: `${pctMax}%`,
              top: '50%',
              transform: 'translate(-50%, -50%)',
              width: `${THUMB_R * 2}px`, height: `${THUMB_R * 2}px`,
              borderRadius: '50%', background: 'white',
              boxShadow: '0px 1px 4px rgba(0,0,0,0.4)',
              cursor: 'pointer', zIndex: 20,
              transition: dragging ? 'none' : 'left 75ms',
            }}
          />
        </div>
      </div>
    </div>
  );
};

export const SegmentedToggle: React.FC<{
  value: string; 
  items: { value: string; label: string; icon?: React.ReactNode }[];
  onChange: (val: string) => void;
}> = ({ value, items, onChange }) => (
  <div style={{
    display: 'flex', width: '100%', alignItems: 'center',
    border: '1px solid #595959', borderRadius: '12px', overflow: 'hidden',
    background: 'transparent'
  }}>
    {items.map((item) => (
      <button key={item.value} type="button" onClick={() => onChange(item.value)}
        style={{
          flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center',
          gap: '4px', height: '34px', padding: '8px', borderRadius: '12px',
          fontSize: '11px', fontWeight: 500, letterSpacing: '0.1px',
          transition: 'all 0.2s', cursor: 'pointer', border: 'none', outline: 'none',
          ...(value === item.value
            ? { background: '#969696', color: 'black' }
            : { background: 'transparent', color: 'rgba(218,220,224,0.75)' }
          )
        }}>
        {item.icon}<span>{item.label}</span>
      </button>
    ))}
  </div>
);

export const TextInput: React.FC<{
  label: string;
  value: string;
  placeholder?: string;
  onChange: (val: string) => void;
  icon?: React.ReactNode;
}> = ({ label, value, placeholder, onChange, icon }) => (
  <div style={{ display: 'flex', flexDirection: 'column', gap: '4px', width: '100%' }}>
    <span style={{
      fontSize: '11px', fontWeight: 500, color: 'rgba(255,255,255,0.35)',
      letterSpacing: '0.1px', padding: '0 8px'
    }}>
      {label}
    </span>
    <div style={{
      display: 'flex', alignItems: 'center', gap: '8px',
      width: '100%', height: '34px', padding: '0 12px', borderRadius: '12px',
      border: '1px solid #595959', background: 'transparent',
      transition: 'all 0.2s'
    }}>
      {icon && <span style={{ color: 'rgba(218,220,224,0.5)', flexShrink: 0 }}>{icon}</span>}
      <input
        type="text"
        value={value}
        placeholder={placeholder}
        onChange={(e) => onChange(e.target.value)}
        style={{
          flex: 1, background: 'transparent', border: 'none', outline: 'none',
          color: 'rgba(218,220,224,0.9)', fontSize: '12px', fontWeight: 500,
          letterSpacing: '0.1px', fontFamily: 'inherit', width: '100%'
        }}
      />
    </div>
  </div>
);

const FONT_OPTIONS = [
  { value: 'monospace', label: 'Monospace' },
  { value: "'Space Mono', monospace", label: 'Space Mono' },
  { value: "'JetBrains Mono', monospace", label: 'JetBrains Mono' },
  { value: "'IBM Plex Mono', monospace", label: 'IBM Plex Mono' },
  { value: "'Fira Code', monospace", label: 'Fira Code' },
  { value: "'Inter', sans-serif", label: 'Inter' },
  { value: "'Outfit', sans-serif", label: 'Outfit' },
  { value: 'sans-serif', label: 'Sans Serif' },
  { value: 'serif', label: 'Serif' },
];

export const FontSelect: React.FC<{
  label: string;
  value: string;
  onChange: (val: string) => void;
}> = ({ label, value, onChange }) => {
  const [open, setOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement | null>(null);

  const selectedFont = FONT_OPTIONS.find(f => f.value === value);

  return (
    <div ref={containerRef} style={{ position: 'relative', width: '100%' }}>
      <span style={{
        fontSize: '11px', fontWeight: 500, color: 'rgba(255,255,255,0.35)',
        letterSpacing: '0.1px',
        padding: '0 8px', display: 'block', marginBottom: '4px'
      }}>
        {label}
      </span>
      <button
        onClick={() => setOpen(!open)}
        style={{
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          width: '100%', height: '34px', padding: '0 12px', borderRadius: '12px',
          border: '1px solid #595959', background: 'transparent', cursor: 'pointer',
          color: 'rgba(218,220,224,0.9)', transition: 'all 0.2s'
        }}
      >
        <span style={{
          fontSize: '11px', fontWeight: 500, fontFamily: value,
          letterSpacing: '0.1px'
        }}>
          {selectedFont?.label || 'Monospace'}
        </span>
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor"
          strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"
          style={{ transform: open ? 'rotate(180deg)' : 'none', transition: 'transform 0.15s' }}>
          <polyline points="6 9 12 15 18 9"/>
        </svg>
      </button>

      {open && (
        <>
          <div
            onClick={() => setOpen(false)}
            style={{ position: 'fixed', inset: 0, zIndex: 99 }}
          />
          <div
            className="animate-dropdown"
            style={{
              position: 'absolute', top: 'calc(100% + 4px)', left: 0, right: 0,
              background: '#1a1a1a', border: '1px solid rgba(255,255,255,0.1)',
              borderRadius: '12px', overflow: 'hidden', zIndex: 100,
              boxShadow: '0 20px 25px -5px rgba(0,0,0,0.5)',
              maxHeight: '200px', overflowY: 'auto'
            }}
          >
            {FONT_OPTIONS.map((font) => (
              <button
                key={font.value}
                onClick={() => { onChange(font.value); setOpen(false); }}
                style={{
                  display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                  width: '100%', padding: '8px 12px', border: 'none',
                  background: value === font.value ? 'rgba(150,150,150,0.15)' : 'transparent',
                  color: value === font.value ? 'white' : 'rgba(218,220,224,0.75)',
                  cursor: 'pointer', transition: 'background 0.1s',
                  fontSize: '11px', fontWeight: 500, fontFamily: font.value,
                  letterSpacing: '0.1px'
                }}
              >
                <span>{font.label}</span>
                {value === font.value && (
                  <span style={{ color: '#969696' }}><CheckIcon size={12} strokeWidth={3} /></span>
                )}
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
};

import { Flow } from 'flow-sdk';
import React from 'react';
import type { TrackerConfig, TrackingMode, SourceType, LabelAlign, LabelPosition, SequenceSort } from '../types';
import { 
  SectionLabel, PillButton, ColorPicker, 
  RangeSlider, DualRangeSlider, SegmentedToggle, Checkbox,
  TextInput, FontSelect 
} from './DesignSystem';

// Inline SVG icon components
const Icon = ({ d, size = 14, strokeWidth = 2 }: { d: string; size?: number; strokeWidth?: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" 
    strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round">{
    d.split('|').map((path, i) => <path key={i} d={path} />)
  }</svg>
);

const CameraIcon = ({ size = 14 }: { size?: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/>
    <circle cx="12" cy="13" r="4"/>
  </svg>
);

const FilmIcon = ({ size = 14 }: { size?: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <rect x="2" y="2" width="20" height="20" rx="2.18" ry="2.18"/>
    <line x1="7" y1="2" x2="7" y2="22"/><line x1="17" y1="2" x2="17" y2="22"/>
    <line x1="2" y1="12" x2="22" y2="12"/><line x1="2" y1="7" x2="7" y2="7"/>
    <line x1="2" y1="17" x2="7" y2="17"/><line x1="17" y1="17" x2="22" y2="17"/>
    <line x1="17" y1="7" x2="22" y2="7"/>
  </svg>
);

const ActivityIcon = ({ size = 14 }: { size?: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/>
  </svg>
);

const ZapIcon = ({ size = 14 }: { size?: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/>
  </svg>
