import { Flow } from 'flow-sdk';
import React, { useEffect, useRef, useState } from 'react';
import type { TrackerConfig } from '../types';
import { PillButton } from './DesignSystem';

interface TrackerViewProps {
  config: TrackerConfig;
  isRunning: boolean;
  setIsRunning: (v: boolean) => void;
  isRecording: boolean;
  setIsRecording: (v: boolean) => void;
  setConfig: React.Dispatch<React.SetStateAction<TrackerConfig>>;
}

class CanvasRecorder {
  private mediaRecorder: MediaRecorder | null = null;
  private chunks: Blob[] = [];
  private stream: MediaStream;

  constructor(stream: MediaStream) {
    this.stream = stream;
  }

  start() {
    this.chunks = [];
    const options = { 
      mimeType: 'video/webm;codecs=vp9,opus',
      videoBitsPerSecond: 25000000 
    };

    if (!MediaRecorder.isTypeSupported(options.mimeType)) {
      options.mimeType = 'video/webm;codecs=vp8,opus';
      if (!MediaRecorder.isTypeSupported(options.mimeType)) {
        options.mimeType = 'video/webm';
      }
    }

    this.mediaRecorder = new MediaRecorder(this.stream, options);

    this.mediaRecorder.ondataavailable = (e) => {
      if (e.data.size > 0) this.chunks.push(e.data);
    };
    this.mediaRecorder.start();
  }

  stop(): Promise<Blob> {
    return new Promise((resolve, reject) => {
      if (!this.mediaRecorder) return reject('Recorder not initialized');

      this.mediaRecorder.onstop = () => {
        const blob = new Blob(this.chunks, { type: 'video/webm' });
        resolve(blob);
      };
      this.mediaRecorder.stop();
    });
  }
}

declare global {
  interface Window {
    cv: any;
    p5: any;
  }
}

export const TrackerView: React.FC<TrackerViewProps> = ({ config, isRunning, setIsRunning, isRecording, setIsRecording, setConfig }) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const videoRef = useRef<any>(null);
  const recorderRef = useRef<CanvasRecorder | null>(null);
  const streamRef = useRef<any>(null);
  const latestFrameRef = useRef<ImageBitmap | null>(null);

  const [cvLoaded, setCvLoaded] = useState(false);
  const [p5Loaded, setP5Loaded] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [videoStatus, setVideoStatus] = useState({ progress: 0, isPlaying: true });
  const [recordingTime, setRecordingTime] = useState(0);

  const configRef = useRef(config);
  const isRunningRef = useRef(isRunning);
  const lastProcessedTimeRef = useRef(0);
  const cachedBlobsRef = useRef<{x: number, y: number, w: number, h: number, id: number}[]>([]);


  useEffect(() => {
    configRef.current = config;
    isRunningRef.current = isRunning;

    if (videoRef.current) {
      if (config.loop) videoRef.current.loop();
      else videoRef.current.noLoop();

      if (!isRunning) videoRef.current.pause();
      else videoRef.current.play();
    }
  }, [config, isRunning]);

  // Handle Recording Logic
  useEffect(() => {
    let timer: ReturnType<typeof setInterval> | undefined;

    const startRecording = () => {
      const canvas = containerRef.current?.querySelector('canvas');
      if (canvas && isRecording) {
        try {
          const fps = configRef.current.processingFPS || 60;
          const canvasStream = canvas.captureStream(fps);

          if (configRef.current.sourceType === 'gallery' && videoRef.current?.elt) {
            try {
              const sourceStream = videoRef.current.elt.captureStream();
              const audioTracks = sourceStream.getAudioTracks();
              audioTracks.forEach((track: MediaStreamTrack) => canvasStream.addTrack(track));
            } catch (audioErr) {
              console.warn("Could not capture audio tracks:", audioErr);
            }
          }

          recorderRef.current = new CanvasRecorder(canvasStream);
          recorderRef.current.start();

          const startTime = Date.now();
          timer = setInterval(() => {
            setRecordingTime(Math.floor((Date.now() - startTime) / 1000));
          }, 1000);
        } catch (e) {
          console.error("Recording start failed", e);
          setIsRecording(false);
        }
      }
    };

    const stopRecording = () => {
      if (recorderRef.current && !isRecording) {
        recorderRef.current.stop().then(blob => {
          const reader = new FileReader();
          reader.onloadend = () => {
            const base64data = (reader.result as string).split(',')[1];
            Flow.save({
              base64: base64data,
              mimeType: 'video/mp4', 
              name: `Tracker Pro Capture ${new Date().toLocaleTimeString()}`
            }).catch(e => console.error("Gallery save failed:", e));
          };
          reader.readAsDataURL(blob);

          recorderRef.current = null;
          setRecordingTime(0);
        }).catch(e => {
          console.error("Recording stop failed", e);
        });
      }
      if (timer) clearInterval(timer);
    };

    if (isRecording) {
      startRecording();
    } else {
      stopRecording();
    }

    return () => {
      if (timer) clearInterval(timer);
    };
  }, [isRecording, setIsRecording]);

  // Specialized Script Loading for OpenCV.js & p5.js
  useEffect(() => {
    // 1. Load OpenCV.js
    if (window.cv?.Mat) {
      setCvLoaded(true);
    } else {
      const cvScript = document.createElement('script');
      cvScript.src = 'https://cdn.jsdelivr.net/npm/@techstark/opencv-js/dist/opencv.js';
      cvScript.async = true;
      cvScript.onload = () => {
        const cv = window.cv;
        if (cv.onRuntimeInitialized !== undefined) {
          cv.onRuntimeInitialized = () => setCvLoaded(true);
        } else if (cv.Mat) {
          setCvLoaded(true);
        } else {
          // Fallback poll
          const poll = setInterval(() => {
            if (window.cv?.Mat) {
              clearInterval(poll);
              setCvLoaded(true);
            }
          }, 100);
        }
      };
      cvScript.onerror = () => setError('Failed to load OpenCV.js engine.');
      document.body.appendChild(cvScript);
    }

    // 2. Load p5.js
    if (window.p5) {
      setP5Loaded(true);
    } else {
      const p5Script = document.createElement('script');
      p5Script.src = 'https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.9.0/p5.min.js';
      p5Script.async = true;
      p5Script.onload = () => setP5Loaded(true);
      p5Script.onerror = () => setError('Failed to load p5.js rendering engine.');
      document.body.appendChild(p5Script);
    }
  }, []);

  // ========== MAIN P5 + OPENCV SKETCH ==========
  useEffect(() => {
    if (!cvLoaded || !p5Loaded || !containerRef.current) return;

    let p5Instance: any;
    let bgSubtractor: any;
    let fgMask: any;
    let gray: any;
    let srcMat: any;
    let srcDataPtr = 0;
    let fgMaskDataPtr = 0;
    let currentW = 0;
    let currentH = 0;
    let readCanvas: HTMLCanvasElement | null = null;
    let readCtx: CanvasRenderingContext2D | null = null;

    const cleanupMats = () => {
      if (fgMask) fgMask.delete();
      if (gray) gray.delete();
      if (srcMat) srcMat.delete();
      fgMask = null;
      gray = null;
      srcMat = null;
      srcDataPtr = 0;
    };

    const startWebcam = () => {
      Flow.camera.stream({ 
        facingMode: 'user', 
        frameRate: configRef.current.processingFPS,
        resolution: 'high' 
      }).then(stream => {
        streamRef.current = stream;
        stream.onFrame(({ bitmap }: any) => {
          if (latestFrameRef.current) latestFrameRef.current.close();
          latestFrameRef.current = bitmap;
        });
      }).catch(e => {
        console.error('Webcam failed:', e);
        setError('Camera access denied or unavailable.');
      });
    };

    const stopWebcam = () => {
      if (streamRef.current) {
        streamRef.current.stop();
        streamRef.current = null;
      }
      if (latestFrameRef.current) {
        latestFrameRef.current.close();
        latestFrameRef.current = null;
      }
    };

    const sketch = (p: any) => {
      p.setup = () => {
        const canvas = p.createCanvas(640, 480);
        canvas.parent(containerRef.current!);

        canvas.elt.style.display = 'block';
        canvas.elt.style.width = 'auto';
        canvas.elt.style.height = 'auto';
        canvas.elt.style.maxWidth = '100%';
        canvas.elt.style.maxHeight = '100%';
        canvas.elt.style.objectFit = 'contain';
        canvas.elt.style.boxShadow = '0 25px 50px -12px rgba(0,0,0,0.5)';
        canvas.elt.style.border = '1px solid rgba(255,255,255,0.1)';

        if (configRef.current.sourceType === 'gallery' && configRef.current.videoUrl) {
          videoRef.current = p.createVideo(configRef.current.videoUrl);
          if (configRef.current.loop) videoRef.current.loop();
          videoRef.current.play();
          videoRef.current.hide();
        } else if (configRef.current.sourceType === 'webcam') {
          startWebcam();
        }

        const cv = window.cv;
        bgSubtractor = new cv.BackgroundSubtractorMOG2(
          configRef.current.history,
          configRef.current.varThreshold,
          true
        );

        readCanvas = document.createElement('canvas');
        readCtx = readCanvas.getContext('2d');
      };

      p.draw = () => {
        if (!isRunningRef.current) return;
        const cfg = configRef.current;
        const cv = window.cv;

        let frameSource: any = null;
        let frameW = 0;
        let frameH = 0;

        if (cfg.sourceType === 'gallery' && videoRef.current) {
          frameSource = videoRef.current.elt;
          frameW = videoRef.current.width || videoRef.current.elt.videoWidth;
          frameH = videoRef.current.height || videoRef.current.elt.videoHeight;
        } else if (cfg.sourceType === 'webcam' && latestFrameRef.current) {
          frameSource = latestFrameRef.current;
          frameW = latestFrameRef.current.width;
          frameH = latestFrameRef.current.height;
        }

        if (!frameSource || frameW <= 0) return;

        if (frameW !== currentW || frameH !== currentH) {
          currentW = frameW;
          currentH = frameH;
          p.resizeCanvas(currentW, currentH);
          cleanupMats();
          fgMask = new cv.Mat(currentH, currentW, cv.CV_8UC1);
          gray = new cv.Mat(currentH, currentW, cv.CV_8UC1);
          srcMat = new cv.Mat(currentH, currentW, cv.CV_8UC4);
          try {
            srcDataPtr = srcMat.data.byteOffset;
            fgMaskDataPtr = fgMask.data.byteOffset;
          } catch (e) {
            srcDataPtr = 0;
            fgMaskDataPtr = 0;
          }
          if (readCanvas) {
            readCanvas.width = currentW;
            readCanvas.height = currentH;
          }
        }

        if (!fgMask) return;

        if (cfg.sourceType === 'gallery' && videoRef.current && p.frameCount % 10 === 0) {
          const duration = videoRef.current.duration();
          const current = videoRef.current.time();
          setVideoStatus({
            progress: duration > 0 ? (current / duration) * 100 : 0,
            isPlaying: !videoRef.current.elt.paused
          });
        }

        const now = Date.now();
        const processingInterval = 1000 / cfg.processingFPS;
        const shouldProcess = (now - lastProcessedTimeRef.current) >= processingInterval;

        p.background(0);

        if (!cfg.showMask) {
          if (cfg.sourceType === 'gallery') {
            p.image(videoRef.current, 0, 0, p.width, p.height);
          } else {
            p.drawingContext.drawImage(frameSource, 0, 0);
          }
        }

        try {
          if (shouldProcess && readCanvas && readCtx && srcMat) {
            readCtx.drawImage(frameSource, 0, 0, currentW, currentH);
            const imageData = readCtx.getImageData(0, 0, currentW, currentH);

            if (srcDataPtr > 0) {
              cv.HEAPU8.set(imageData.data, srcDataPtr);
            }

            if (cfg.mode === 'moving') {
              bgSubtractor.apply(srcMat, fgMask, -1);
              cv.threshold(fgMask, fgMask, cfg.threshold, 255, cv.THRESH_BINARY);
            } else {
              cv.cvtColor(srcMat, gray, cv.COLOR_RGBA2GRAY);
              cv.threshold(gray, fgMask, cfg.threshold, 255, cv.THRESH_BINARY);
              const M = cv.Mat.ones(3, 3, cv.CV_8U);
              cv.erode(fgMask, fgMask, M);
              cv.dilate(fgMask, fgMask, M);
              M.delete();
            }

            const contours = new cv.MatVector();
            const hierarchy = new cv.Mat();
            cv.findContours(fgMask, contours, hierarchy, cv.RETR_EXTERNAL, cv.CHAIN_APPROX_SIMPLE);

            let blobCenters: {x: number, y: number, w: number, h: number, id: number}[] = [];

            for (let i = 0; i < contours.size(); i++) {
              const contour = contours.get(i);
              const area = cv.contourArea(contour);

              if (area > cfg.minArea && area < cfg.maxArea) {
                const r = cv.boundingRect(contour);
                const centerX = r.x + (r.width / 2);
                const centerY = r.y + (r.height / 2);
                blobCenters.push({ x: centerX, y: centerY, w: r.width, h: r.height, id: i });
              }
              contour.delete();
            }

            if (cfg.sequenceSort === 'x') {
              blobCenters.sort((a, b) => a.x - b.x);
            } else {
              blobCenters.sort((a, b) => a.y - b.y);
            }

            cachedBlobsRef.current = blobCenters;
            lastProcessedTimeRef.current = now;

            contours.delete();
            hierarchy.delete();
          }

          const currentBlobs = cachedBlobsRef.current;

          if (cfg.showMask && fgMask && fgMaskDataPtr > 0) {
            const maskImg = p.createImage(currentW, currentH);
            maskImg.loadPixels();
            const pixelCount = currentW * currentH;
            for (let i = 0; i < pixelCount; i++) {
              const val = cv.HEAPU8[fgMaskDataPtr + i];
              const idx = i * 4;
              maskImg.pixels[idx] = val;
              maskImg.pixels[idx + 1] = val;
              maskImg.pixels[idx + 2] = val;
              maskImg.pixels[idx + 3] = 255;
            }
            maskImg.updatePixels();
            p.image(maskImg, 0, 0);
          }

          if (cfg.connectSequence && currentBlobs.length > 1) {
            p.noFill(); p.stroke(cfg.trackerColor + 'CC'); p.strokeWeight(cfg.strokeWeight);
            p.beginShape();
            for (const pt of currentBlobs) p.vertex(pt.x, pt.y);
            p.endShape();
          }

          if (cfg.connectNearby) {
            p.stroke(cfg.trackerColor + '40'); p.strokeWeight(cfg.strokeWeight / 2);
            for (let i = 0; i < currentBlobs.length; i++) {
              for (let j = i + 1; j < currentBlobs.length; j++) {
                const d = p.dist(currentBlobs[i].x, currentBlobs[i].y, currentBlobs[j].x, currentBlobs[j].y);
                if (d < cfg.connectionMaxDist) {
                  p.line(currentBlobs[i].x, currentBlobs[i].y, currentBlobs[j].x, currentBlobs[j].y);
                }
              }
            }
          }

          for (const blob of currentBlobs) {
            const rx = blob.x - (blob.w / 2);
            const ry = blob.y - (blob.h / 2);
            p.stroke(cfg.trackerColor); p.strokeWeight(cfg.strokeWeight); p.noFill();
            p.rect(rx, ry, blob.w, blob.h, cfg.borderRadius);
            if (cfg.showCenterDot) {
              p.fill(cfg.trackerColor); p.noStroke();
              p.circle(blob.x, blob.y, 6 + cfg.strokeWeight);
            }
            if (cfg.showLabels) {
              p.push();
              p.noStroke();
              p.strokeWeight(0);
              p.textFont(cfg.fontFamily);
              p.textSize(cfg.labelSize);
              const lc = cfg.labelColor || '#ffffff';
              const r2 = parseInt(lc.slice(1,3), 16);
              const g2 = parseInt(lc.slice(3,5), 16);
              const b2 = parseInt(lc.slice(5,7), 16);
              p.fill(r2, g2, b2);
              const labelText = cfg.showLabelNumber 
                ? `${cfg.labelPrefix}${blob.id}` 
                : cfg.labelPrefix;
              const hAlign = cfg.labelAlign === 'center' ? p.CENTER 
                           : cfg.labelAlign === 'right' ? p.RIGHT 
                           : p.LEFT;
              const lx = cfg.labelAlign === 'center' ? blob.x 
                       : cfg.labelAlign === 'right' ? rx + blob.w 
                       : rx;
              if (cfg.labelPosition === 'bottom') {
                p.textAlign(hAlign, p.TOP);
                p.text(labelText, lx, ry + blob.h + 4);
              } else {
                p.textAlign(hAlign, p.BOTTOM);
                p.text(labelText, lx, ry - 4);
              }
              p.pop();
            }
          }

        } catch (e) {
          console.error("Tracking Error:", e);
        }
      };
    };

    p5Instance = new window.p5(sketch);
    return () => {
      if (p5Instance) p5Instance.remove();
      if (bgSubtractor) bgSubtractor.delete();
      stopWebcam();
      cleanupMats();
    };
  }, [cvLoaded, p5Loaded, config.videoUrl, config.sourceType]);

  const handleUploadVideo = () => {
    Flow.media.select({ filter: 'video' }).then(media => {
      if (!media) return;
      const bytes = Uint8Array.from(atob(media.base64), c => c.charCodeAt(0));
      const blob = new Blob([bytes], { type: media.mimeType });
      const objectUrl = URL.createObjectURL(blob);
      setConfig(prev => ({
        ...prev,
        sourceType: 'gallery' as const,
        videoUrl: objectUrl
      }));
    }).catch(e => {
      console.error('Media selection failed:', e);
    });
  };

  if (error) return (
    <div style={{
      display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '16px',
      color: '#f87171', background: 'rgba(248,113,113,0.1)', padding: '32px',
