        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.borderColor = 'rgba(218,220,224,0.2)';
          e.currentTarget.style.background = 'rgba(255,255,255,0.02)';
        }}
      >
        <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" style={{ opacity: 0.5 }}>
          <rect x="2" y="2" width="20" height="20" rx="2.18" ry="2.18"/>
          <line x1="7" y1="2" x2="7" y2="22"/><line x1="17" y1="2" x2="17" y2="22"/>
          <line x1="2" y1="12" x2="22" y2="12"/><line x1="2" y1="7" x2="7" y2="7"/>
          <line x1="2" y1="17" x2="7" y2="17"/><line x1="17" y1="17" x2="22" y2="17"/>
          <line x1="17" y1="7" x2="22" y2="7"/>
        </svg>
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
          <span style={{
            fontSize: '14px', fontWeight: 600, letterSpacing: '0.02em',
            color: 'rgba(218,220,224,0.8)'
          }}>
            Load a Video
          </span>
          <span style={{
            fontSize: '11px', fontWeight: 500, letterSpacing: '0.05em',
            color: 'rgba(218,220,224,0.35)'
