            Select a video file to begin tracking
          </span>
        </div>
      </button>
    </div>
  );

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (videoRef.current) {
      const duration = videoRef.current.duration();
      videoRef.current.time((Number(e.target.value) / 100) * duration);
    }
  };


  return (
    <div style={{
