            </button>
            <div style={{ flex: 1 }}>
              <input 
                type="range" 
                min="0" max="100" 
                value={videoStatus.progress} 
                onChange={handleSeek}
                style={{ width: '100%' }} 
              />
            </div>
          </div>
          <div style={{
            display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '0 4px'
          }}>
            <span style={{
              fontSize: '10px', fontWeight: 500, color: 'rgba(255,255,255,0.35)',
              letterSpacing: '0.1px'
            }}>
              {videoRef.current ? Math.floor(videoRef.current.time()) : 0}s / {videoRef.current ? Math.floor(videoRef.current.duration()) : 0}s
            </span>
            <span style={{
              fontSize: '10px', fontWeight: 500, color: '#c7c9cd',
              letterSpacing: '0.1px'
